begin;
create temporary table care_test(a uuid,b uuid,c uuid,sid uuid,code text);
insert into care_test values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null);
insert into auth.users(id,aud,role,email) select a,'authenticated','authenticated',a||'@care-test.invalid' from care_test union all select b,'authenticated','authenticated',b||'@care-test.invalid' from care_test union all select c,'authenticated','authenticated',c||'@care-test.invalid' from care_test;
grant select,update on care_test to authenticated;
create function pg_temp.assert_care(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from care_test;
update care_test set sid=public.create_partner_space_with_role('user_1');
update care_test set code=public.issue_pair_code()->>'code';
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from care_test;
select public.redeem_pair_code_with_role(code,'user_2') from care_test;
select public.save_care_share(sid,true,'{"cycle":30,"duration":6,"logs":[{"day":20743,"start":true,"end":false,"flow":"Light","cramps":"Mild","mood":2,"cravings":["Chocolate"],"symptoms":[],"note":"Test day"}]}'::jsonb,0) from care_test;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from care_test;
select pg_temp.assert_care((select count(*) from public.care_shares)=1,'partner can read enabled snapshot');
select pg_temp.assert_care((select payload->>'cycle' from public.care_shares where user_id=(select b from care_test))='30','partner sees owner cycle');
with changed as (update public.care_shares set payload='{"cycle":99,"duration":5,"logs":[]}' where user_id=(select b from care_test) returning *) select pg_temp.assert_care(count(*)=0,'partner cannot update owner care') from changed;
with removed as (delete from public.care_shares where user_id=(select b from care_test) returning *) select pg_temp.assert_care(count(*)=0,'partner cannot delete owner care') from removed;
do $$declare t care_test;begin select * into t from care_test;
 begin insert into public.care_shares(space_id,user_id,enabled,payload) values(t.sid,t.b,false,'{}');raise exception 'FAILED: cannot impersonate owner';exception when insufficient_privilege then null;end;
end$$;
select public.save_care_share(sid,true,'{"cycle":28,"duration":5,"logs":[]}',0) from care_test;
select pg_temp.assert_care((select count(*) from public.care_shares)=2,'separate snapshots for both owners');
select pg_temp.assert_care((select payload->>'cycle' from public.care_shares where user_id=(select b from care_test))='30','my update does not alter partner data');
do $$declare t care_test;begin select * into t from care_test;
 begin perform public.save_care_share(t.sid,true,'{"cycle":31,"duration":5,"logs":[]}',0);raise exception 'FAILED: stale version accepted';exception when serialization_failure then null;end;
 begin perform public.save_care_share(t.sid,true,'{"cycle":1,"duration":5,"logs":[]}',1);raise exception 'FAILED: invalid cycle';exception when check_violation then null;end;
 begin perform public.save_care_share(t.sid,true,'{"cycle":28,"duration":5,"logs":[],"token":"forbidden"}',1);raise exception 'FAILED: extra data accepted';exception when check_violation then null;end;
end$$;
select public.save_care_share(sid,false,'{}',1) from care_test;
select pg_temp.assert_care((select payload from public.care_shares where user_id=(select a from care_test))='{}','revoke removes shared payload');
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from care_test;
select pg_temp.assert_care((select count(*) from public.care_shares)=1,'revocation hides partner row');
select public.mutate_shared_record(gen_random_uuid(),sid,'appreciation',null,null,jsonb_build_object('kind','CareSupport','message','Here for you','taskTitle',a::text,'picture','','at',1),0,gen_random_uuid(),false) from care_test;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from care_test;
select pg_temp.assert_care((select count(*) from public.shared_records where kind='appreciation' and payload->>'kind'='CareSupport')=1,'support note is separate and visible to partner');
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true) from care_test;
select pg_temp.assert_care((select count(*) from public.care_shares)=0,'outsider cannot read care');
do $$declare t care_test;begin select * into t from care_test;
 begin perform public.save_care_share(t.sid,true,'{"cycle":28,"duration":5,"logs":[]}',0);raise exception 'FAILED: outsider care write accepted';exception when insufficient_privilege then null;end;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from care_test;
select public.leave_partner_space();
select pg_temp.assert_care((select count(*) from public.care_shares)=0,'unpair revokes own care access');
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from care_test;
select pg_temp.assert_care((select count(*) from public.care_shares)=0,'unpair revokes partner care access');
set local role anon;
select pg_temp.assert_care(not has_table_privilege('anon','public.care_shares','SELECT'),'anonymous care read denied');
reset role;
select 'PASS: independent owner records, partner read-only, ownership impersonation rejected, stale writes rejected, payload validation, revocation clears payload, separate support notes, outsider/anonymous isolation and unpair revocation' as result;
rollback;
